// #1a311effdd4a2d2ba5fe9c67 — сбой сети при старте официального звонка: объяснение, «נסו שוב», путь к человеку;
// неудачный старт не тратит попытку (статус у бизнеса); после восстановления сети звонок стартует ровно один раз
// с подсказкой открыть приветствием. Кейсы CALL-003, CALL-004.
// НЕ prod-safe: создаёт кандидата «QA-AUTO-CALL-O-…» (link_only); последний тест (@slow) ТРАТИТ официальную попытку и AI.
// Кандидат не удаляется (правило проекта). Сбой — настоящий context.setOffline(true).
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import {
  Candidate, TXT, createCandidateLink, candidateRow, launchCandidate, goToPractice, goToOfficialConfirm, tap,
  expectStartFailure, expectHelpPath, waitConnectingHint,
} from './support';

test.describe.configure({ mode: 'serial' });

let cand: Candidate | undefined;
let name = '';

test.afterAll(async () => {
  await cand?.browser.close();
});

test.describe('Звонок кандидата — сбой старта официального звонка (#1a311effdd4a2d2ba5fe9c67) @call', () => {
  test('offline → «מוכן, מתחילים»: объяснение про «השיחה … תקלה בחיבור לאינטרנט», «נסו שוב», путь к человеку @desktop @data #1a311effdd4a2d2ba5fe9c67', async ({ asUser }) => {
    test.setTimeout(5 * 60_000);
    const business = await asUser('business');
    name = `QA-AUTO-CALL-O-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}», не удаляется` });

    cand = await launchCandidate({ width: 390, height: 844 });
    const { page, ctx, counts } = cand;
    await goToPractice(page, link);
    await goToOfficialConfirm(page);

    // Источник: AC — «כשל רשת בבקשת התחלת … השיחה הרשמית מציג למועמד הסבר, ניסיון חוזר ונתיב פנייה».
    await ctx.setOffline(true);
    await tap(page, 'מוכן, מתחילים');
    await expectStartFailure(page, TXT.officialFail);
    expect(counts.start, 'запросов candidate_start_attempt на одно нажатие').toBe(1);

    await expectHelpPath(page, TXT.officialFail);

    await tap(page, TXT.retry);
    await expect.poll(() => counts.start).toBe(2);
    await expectStartFailure(page, TXT.officialFail);
    expect(counts.voice, 'start-voice-session без сети').toBe(0);
  });

  test('business: после неудачного старта статус кандидата «בדיקה טכנית החלה» — попытка не потрачена @desktop @data #1a311effdd4a2d2ba5fe9c67', async ({ asUser }) => {
    expect(name, 'нет кандидата из предыдущего теста').not.toBe('');
    const business = await asUser('business');
    const row = await candidateRow(business, name);
    // Источник: D-12 (одна официальная попытка, повтор только при сбое); S-15 «הניסיון הרשמי נותר זמין ולא נצרך».
    await expect(row).toContainText('בדיקה טכנית החלה');
    for (const bad of ['הסימולציה החלה', 'תקלה טכנית', 'הושלמה']) await expect(row).not.toContainText(bad);
  });

  test('сеть восстановлена → «נסו שוב»: официальный звонок стартует ровно 1 раз с подсказкой «פתחו בברכה»; у бизнеса «הושלמה» @desktop @data @slow #1a311effdd4a2d2ba5fe9c67', async ({ asUser }) => {
    test.setTimeout(6 * 60_000);
    expect(cand, 'нет состояния из первого теста').toBeTruthy();
    const { page, ctx, counts } = cand!;
    const before = counts.start;
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}»: официальная попытка использована` });

    await ctx.setOffline(false);
    const hint = waitConnectingHint(page);
    await tap(page, TXT.retry);

    // Источник: «מה רצוי» — «מסך ההתחברות מציג את ההנחיה לפתוח בברכה».
    expect(await hint).toBe(TXT.hint);
    await expect(page.getByText('הניסיון הרשמי')).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('button', { name: 'לסיים שיחה' })).toBeVisible();
    // Источник: AC — «ניסיון חוזר»; D-12 — одна попытка: повтор стартует один раз.
    expect(counts.start - before, 'candidate_start_attempt после повтора').toBe(1);
    expect(counts.voice, 'start-voice-session после повтора').toBe(1);

    await tap(page, 'לסיים שיחה');
    await tap(page, 'לאשר סיום שיחה');
    await expect(page.getByText('הסימולציה הושלמה')).toBeVisible({ timeout: 60_000 });
    expect(counts.voice, 'второй старт звонка').toBe(1);

    const business = await asUser('business');
    const row = await candidateRow(business, name);
    await expect(row).toContainText('הושלמה', { timeout: 30_000 });
  });
});
